import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;
    static long p, k;
    static int[] visited;

    static int findCycleLength(int start) {
        int length = 1;
        visited[(int)start] = 1;
        int current = (int)start;
        while (visited[(int)((current * k) % p)] == 0) {
            current = (int)((current * k) % p);
            length++;
            visited[current] = 1;
        }
        return length;
    }

    static long modPow(long base, long exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) result = (result * base) % p;
            base = (base * base) % p;
            exponent >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p = sc.nextLong();
        k = sc.nextLong();
        visited = new int[(int)p];
        long answer = 1;
        for (int i = 1; i < p; i++) {
            if (visited[i] == 0) {
                int cycleSize = findCycleLength(i);
                long powerValue = modPow(k, cycleSize);
                if (powerValue != 1 && powerValue != 0)
                    answer = (answer * (cycleSize + 1)) % MOD;
                else
                    answer = (answer * p) % MOD;
            }
        }
        if (k == 1) answer = (answer * p) % MOD;
        System.out.println(answer);
        sc.close();
    }
}
